// PokePoke omp integration - auto-generated by `poke-hook --install-omp`.
// pokepoke-plugin-marker
// Do not edit by hand; re-run Connect from the PokePoke tray to regenerate.
//
// omp(oh-my-pi,pi 的 fork)扩展接入。相对 pi 变体的四处必要差异:
//   1. **没有 `agent_settled`**:omp 的扩展事件目录里 settle 由 `agent_end` +
//      `willContinue !== true` 表达(omp 在扩展事件对象字面量上恒定带 willContinue
//      属性,pi 的 `agent_end` 不带 —— 故可用 `"willContinue" in event` 做能力探测,
//      同一份代码在两个宿主上都不会误判);
//   2. **一个进程可能承载多个 session**:`task` tool 的 subagent 会在同一进程里
//      再执行一次本工厂,且 sub-session 的 session id 前 8 字符与父 session 相同
//      (都是 UUIDv7 时间戳前缀)→ PokePoke 的 `omp-<sid8>` task_id 会与父撞车,
//      sub-session 的 settle 会冒充父 session 的"完成"。故按
//      `ctx.localProtocolOptions.getSessionId()`(父 session id)过滤 sub-session;
//   3. **有原生审批事件** `tool_approval_requested`(pi 没有)→ 归一成
//      `PermissionRequest`,server 端进 Pending(等价 CC 的权限确认);
//   4. **上报状态必须挂在工厂闭包上,不能放模块级**:omp 对同进程内的 subagent
//      工厂复用**同一个已 import 的模块实例**(父 session 的 preparedExtensions
//      直接 rebind 再跑一次工厂,见 omp 18.2.11 `bindPreparedExtensions`),模块级
//      可变状态会被子 session 串改 —— 2026-09-24 实测:sub-session 的 session_start
//      把模块级 `tracking` 置 false 后,父 session 的 Stop / SessionEnd 全部被吞,
//      session 卡 Running 直到 reaper 清。
// 所有失败一律 swallow,提醒失败绝不影响 omp 会话。仅 `ctx.mode === "tui"` 时上报。
import { spawn } from "node:child_process";

const POKE_HOOK = "__POKE_HOOK_BIN__";

// Dedupe SessionStart per session id within this process:
// each SessionStart triggers a Ghostty terminal_id capture server-side,
// and a duplicate capture can race and bind the wrong tab.
const seenSessions = new Set();
const DEDUP_CAP = 2000;
function remember(set, id) {
  if (set.size >= DEDUP_CAP) set.clear();
  set.add(id);
}

function forward(payload) {
  try {
    const child = spawn(POKE_HOOK, ["--source=omp"], {
      stdio: ["pipe", "ignore", "ignore"],
    });
    child.on("error", () => {});
    child.stdin.on("error", () => {});
    child.stdin.write(JSON.stringify(payload));
    child.stdin.end();
  } catch {
    // never let a notification failure surface into omp
  }
}

// ---- session 归属 ----
// 下面三个判定都是无状态纯函数。**上报状态(tracking / trackedId / trackedCwd)与
// register / syncSession 都在工厂闭包内**(见 export default 内的注释与头注 4):
// 同进程内的 subagent 复用同一个模块实例再跑一次工厂,模块级状态会被子 session 串改。

function sessionIdOf(ctx) {
  try {
    return ctx?.sessionManager?.getSessionId?.() ?? undefined;
  } catch {
    return undefined;
  }
}

// subagent / eval 子 session 判别:omp 把父 session 的 id 放进 localProtocolOptions。
// 字段缺失或抛错时保守判为父 session —— 宁可多追踪一个真 session,也不误杀它。
function isSubSession(ctx) {
  try {
    const own = sessionIdOf(ctx);
    const root = ctx?.localProtocolOptions?.getSessionId?.();
    return Boolean(own && root && root !== own);
  } catch {
    return false;
  }
}

function tuiOnly(ctx) {
  return ctx?.mode === "tui";
}

// ---- StopFailure:provider errors that end a turn ----
// omp 的 agent_end 带最终 assistant message,其 stopReason 区分 "error"(provider/API
// 失败)与 "aborted"(用户取消)。willContinue === true 表示已安排自动续跑
// (auto-retry / compaction / queued follow-up),不是终态 —— 判据与 pi 的
// agent_settled 对齐:只有 `willContinue !== true` 的那次 agent_end 才落终态。
const MAX_ERROR_DETAIL = 300;
function truncateDetail(s) {
  if (typeof s !== "string" || s.length <= MAX_ERROR_DETAIL) return s || "";
  return s.slice(0, MAX_ERROR_DETAIL - 3) + "...";
}
function errorDetailOf(message) {
  if (!message) return "";
  if (typeof message.errorMessage === "string" && message.errorMessage) {
    return message.errorMessage;
  }
  const content = message.content;
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    const text = content
      .filter((p) => p && p.type === "text" && typeof p.text === "string")
      .map((p) => p.text)
      .join(" ");
    if (text) return text;
  }
  return "";
}
function finalAssistantMessage(messages) {
  if (!Array.isArray(messages)) return undefined;
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i] && messages[i].role === "assistant") return messages[i];
  }
  return undefined;
}

export default function (pi) {
  // ---- 本实例(一次工厂执行)当前上报的 session ----
  // **必须在工厂闭包内**:omp 对同进程内的 subagent 复用同一个模块实例再跑一次
  // 工厂(头注 4),提到模块级会被子 session 串改 —— 父 session 的 Stop/SessionEnd
  // 会被子 session 的 session_start 静默。omp 的 /new、/resume、/fork 在同进程内
  // 换 session,ctx.sessionManager 每次都是当前 session,故每个事件都重新对齐一次。
  let trackedId = undefined;
  let trackedCwd = "";
  // false: subagent 子 session —— 本实例全程静默,不上报任何事件。
  let tracking = true;

  // 首次登记(或换 session 后重登记)。trackedId 已存在且与新 id 不同时,
  // 先给旧 session 收尾(SessionEnd),保证面板不留悬空会话。
  function register(ctx) {
    if (!tracking || !tuiOnly(ctx) || isSubSession(ctx)) return undefined;
    const id = sessionIdOf(ctx);
    if (!id) return undefined; // ephemeral(无 session 文件):没有稳定身份
    if (trackedId && trackedId !== id) {
      forward({ hook_event_name: "SessionEnd", session_id: trackedId, cwd: trackedCwd });
      trackedId = undefined;
    }
    trackedId = id;
    trackedCwd = ctx?.cwd ?? "";
    if (!seenSessions.has(id)) {
      remember(seenSessions, id);
      forward({ hook_event_name: "SessionStart", session_id: id, cwd: trackedCwd });
    }
    return id;
  }

  // 事件前的 session 对齐:返回 true 表示该事件可以上报。
  function syncSession(ctx) {
    if (!tracking || !trackedId) return false;
    const id = sessionIdOf(ctx);
    if (id && id !== trackedId) {
      // 静默换 session:先给旧 session 收尾,再登记新的
      forward({ hook_event_name: "SessionEnd", session_id: trackedId, cwd: trackedCwd });
      trackedId = undefined;
      return Boolean(register(ctx));
    }
    if (ctx?.cwd) trackedCwd = ctx.cwd;
    return true;
  }

  // turnFailed = provider error(stopReason "error")-> StopFailure
  // turnAborted = 用户取消(stopReason "aborted")-> Stop + aborted:true
  //   (server 据此抑制"完成"音,与 pi / cursor 对齐)
  let turnFailed = false;
  let turnAborted = false;
  let turnErrorDetail = "";

  pi.on("session_start", async (_event, ctx) => {
    try {
      if (isSubSession(ctx)) {
        // subagent 子 session:与父 session 共享 task_id,上报会冒充父的完成。
        // 只静默本实例(工厂闭包状态),父 session 的上报通道不受影响。
        tracking = false;
        return;
      }
      register(ctx);
    } catch {}
  });

  // 同实例换 session(/new、/resume、/fork):omp 未必重跑扩展工厂,这里显式补登记。
  pi.on("session_switch", async (_event, ctx) => {
    try {
      register(ctx);
    } catch {}
  });

  pi.on("before_agent_start", async (_event, ctx) => {
    try {
      if (!syncSession(ctx)) return;
      turnFailed = false;
      turnAborted = false;
      turnErrorDetail = "";
      forward({ hook_event_name: "UserPromptSubmit", session_id: trackedId, cwd: trackedCwd });
    } catch {}
  });

  // 审批请求 -> Pending(等价 CC 的 PermissionRequest)。
  // 审批结果不上报:与 CC permission_prompt 现状一致(下一个事件自然带走 Pending)。
  pi.on("tool_approval_requested", async (event, ctx) => {
    try {
      if (!syncSession(ctx)) return;
      const tool = event && typeof event.toolName === "string" ? event.toolName : "";
      forward({
        hook_event_name: "PermissionRequest",
        session_id: trackedId,
        cwd: trackedCwd,
        tool_name: tool,
      });
    } catch {}
  });

  pi.on("agent_end", async (event, ctx) => {
    try {
      // 能力探测:只有 omp 的 agent_end 带 willContinue 属性;pi 的 agent_end
      // 由 agent_settled 表达终态。缺该属性说明本文件被别的宿主(pi)加载,静默退出。
      if (!event || !("willContinue" in event)) return;
      if (event.willContinue === true) return; // 还会自动续跑,不是终态
      if (!syncSession(ctx)) return;
      const last = finalAssistantMessage(event.messages);
      const stopReason = last && last.stopReason;
      if (stopReason === "error") {
        forward({
          hook_event_name: "StopFailure",
          session_id: trackedId,
          cwd: trackedCwd,
          reason: "provider_error",
          detail: truncateDetail(errorDetailOf(last)) || "Provider request failed",
        });
        turnErrorDetail = "";
        return;
      }
      if (stopReason === "aborted") {
        // 用户取消:不是 provider 失败,但也不是正常完成 ——
        // 发 Stop + aborted:true,server 抑制"完成"音。
        forward({
          hook_event_name: "Stop",
          session_id: trackedId,
          cwd: trackedCwd,
          aborted: true,
        });
        return;
      }
      forward({ hook_event_name: "Stop", session_id: trackedId, cwd: trackedCwd });
    } catch {}
  });

  // Auxiliary signal: a provider returned 429/5xx. Only enriches the failure
  // detail; never the failure verdict. Skip when the detail already carries
  // that status (errorMessage usually repeats it).
  pi.on("after_provider_response", async (event) => {
    try {
      if (!tracking || !trackedId) return;
      const status = event && event.status;
      if (typeof status === "number" && (status === 429 || status >= 500)) {
        if (!turnErrorDetail.includes("HTTP " + status)) {
          turnErrorDetail = turnErrorDetail
            ? "HTTP " + status + " · " + turnErrorDetail
            : "HTTP " + status;
        }
      }
    } catch {}
  });

  // reason: "quit" | "reload" | "new" | "resume" | "fork" —— 无论哪种,本实例当前
  // 跟踪的 session id 到这里都不再存活;若 omp 用新实例继续(换 session),新实例
  // 走自己的 session_start / session_switch 重登记。
  pi.on("session_shutdown", async () => {
    try {
      if (!tracking || !trackedId) return;
      forward({ hook_event_name: "SessionEnd", session_id: trackedId, cwd: trackedCwd });
      trackedId = undefined;
    } catch {}
  });
}
